// BUG: returns lowercase instead of uppercase
pub fn trim_and_upper(s: &str) -> String {
    s.trim().to_lowercase()
}

// BUG: counts bytes/characters instead of whitespace-separated words
pub fn count_words(s: &str) -> usize {
    s.len()
}

// BUG: splits on whitespace instead of commas
pub fn split_on_comma(s: &str) -> Vec<String> {
    s.split_whitespace().map(|p| p.to_string()).collect()
}

use strparser::{trim_and_upper, count_words, split_on_comma};

#[test]
fn test_trim_and_upper() {
    assert_eq!(trim_and_upper("  hello  "), "HELLO");
}

#[test]
fn test_count_words() {
    assert_eq!(count_words("the quick brown fox"), 4);
    assert_eq!(count_words("hello"), 1);
}

#[test]
fn test_split_on_comma() {
    assert_eq!(split_on_comma("a,b,c"), vec!["a", "b", "c"]);
}

#[test]
fn test_trim_preserves_content() {
    assert_eq!(trim_and_upper("  rust  "), "RUST");
}

#[test]
fn test_split_on_comma_single() {
    assert_eq!(split_on_comma("only"), vec!["only"]);
}
